fn sign(x: Vec<i8>) -> Vec<i8> {
    x.into_iter()
        .map(|v| {
            if v < 0 {
                -1
            } else if v > 0 {
                1
            } else {
                0
            }
        })
        .collect()
}

fn main() {
    // Example usage:
    let input = vec![-5, 0, 3, -1, 2];
    let output = sign(input);
    assert_eq!(output, vec![-1, 0, 1, -1, 1]);
    println!("sign classification succeeded: {:?}", output);
}